6	    // Convert image to base64 data URL
7	    async function imageToBase64(imgElement) {
8	        const src = imgElement.getAttribute('src') || '';
9	
10	        // Skip UI images
11	        if (src.includes('favicon') || src.includes('avatar')) {
12	            return null;
13	        }
14	
15	        try {
16	            // For blob URLs, we can draw directly from the existing image
17	            if (src.startsWith('blob:') || imgElement.complete) {
18	                return drawImageToBase64(imgElement);
19	            }
20	
21	            // For other URLs, load the image first
22	            return new Promise((resolve) => {
23	                const img = new Image();
24	                img.crossOrigin = 'anonymous';
25	                img.onload = () => resolve(drawImageToBase64(img));
26	                img.onerror = () => {
27	                    console.warn('Failed to load image:', src);
28	                    resolve(null);
29	                };
30	                img.src = src;
31	                // Timeout after 5 seconds
32	                setTimeout(() => resolve(null), 5000);
33	            });
34	        } catch (e) {
35	            console.warn('Error converting image to base64:', e);
36	            return null;
37	        }
38	    }
