40	    function drawImageToBase64(img) {
41	        try {
42	            const canvas = document.createElement('canvas');
43	            canvas.width = img.naturalWidth || img.width;
44	            canvas.height = img.naturalHeight || img.height;
45	
46	            if (canvas.width === 0 || canvas.height === 0) {
47	                return null;
48	            }
49	
50	            const ctx = canvas.getContext('2d');
51	            ctx.drawImage(img, 0, 0);
52	            return canvas.toDataURL('image/png');
53	        } catch (e) {
54	            // CORS or other error
55	            console.warn('Cannot draw image to canvas:', e);
56	            return null;
57	        }
58	    }
