156	    function convertElementToMarkdown(element) {
157	        if (!element) return '';
158	
159	        // Handle text nodes
160	        if (element.nodeType === Node.TEXT_NODE) {
161	            return element.textContent || '';
162	        }
163	
164	        // Skip non-element nodes
165	        if (element.nodeType !== Node.ELEMENT_NODE) {
166	            return '';
167	        }
168	
169	        const tagName = element.tagName.toLowerCase();
170	
171	        // Skip UI elements (but check button for images first)
172	        if (tagName === 'button') {
173	            // Check if button contains an image (ChatGPT wraps images in buttons)
174	            const img = element.querySelector('img');
175	            if (img) {
176	                return convertElementToMarkdown(img);
177	            }
178	            return '';
179	        }
180	        if (['svg', 'script', 'style', 'noscript'].includes(tagName)) {
181	            return '';
182	        }
183	
184	        // Skip elements with specific classes (UI components)
185	        const className = element.className || '';
186	        if (typeof className === 'string' &&
187	            (className.includes('copy') || className.includes('edit') ||
188	             className.includes('regenerate') || className.includes('citation-pill'))) {
189	            return '';
190	        }
191	
192	        // Process by tag type
193	        switch (tagName) {
194	            // Headings
195	            case 'h1':
196	                return '\n\n# ' + getTextContent(element) + '\n\n';
197	            case 'h2':
198	                return '\n\n## ' + getTextContent(element) + '\n\n';
199	            case 'h3':
200	                return '\n\n### ' + getTextContent(element) + '\n\n';
201	            case 'h4':
202	                return '\n\n#### ' + getTextContent(element) + '\n\n';
203	            case 'h5':
204	                return '\n\n##### ' + getTextContent(element) + '\n\n';
205	            case 'h6':
206	                return '\n\n###### ' + getTextContent(element) + '\n\n';
207	
208	            // Paragraph
209	            case 'p':
210	                return '\n\n' + processChildNodes(element) + '\n\n';
211	
212	            // Bold
213	            case 'strong':
214	            case 'b':
215	                return '**' + processChildNodes(element) + '**';
216	
217	            // Italic
218	            case 'em':
219	            case 'i':
220	                return '*' + processChildNodes(element) + '*';
221	
222	            // Code (inline)
223	            case 'code':
224	                // Check if it's inside a pre block
225	                if (element.parentElement && element.parentElement.tagName.toLowerCase() === 'pre') {
226	                    return element.textContent || '';
227	                }
228	                return '`' + (element.textContent || '') + '`';
229	
230	            // Code blocks
231	            case 'pre': {
232	                const codeEl = element.querySelector('code');
233	                const code = element.textContent || '';
234	                let lang = '';
