305	
306	            // Span and other inline elements - just process children
307	            case 'span':
308	            case 'div':
309	            case 'article':
310	            case 'section':
311	            case 'main':
312	            case 'header':
313	            case 'footer':
314	            case 'aside':
315	            case 'nav':
316	                return processChildNodes(element);
317	
318	            // Skip hidden elements
319	            case 'template':
320	                return '';
321	
322	            default:
323	                return processChildNodes(element);
324	        }
325	    }
