340	    async function processMessageContent(element) {
341	        const clone = element.cloneNode(true);
342	
343	        // Extract images from buttons before removing them (ChatGPT wraps images in buttons)
344	        clone.querySelectorAll('button').forEach(btn => {
345	            const img = btn.querySelector('img');
346	            if (img) {
347	                // Replace button with the image
348	                btn.parentNode.replaceChild(img.cloneNode(true), btn);
349	            } else {
350	                btn.remove();
351	            }
352	        });
353	
354	        // Remove UI elements that shouldn't be in the export
355	        clone.querySelectorAll('svg, [class*="sr-only"], [class*="citation-pill"]').forEach(el => el.remove());
356	
357	        // Pre-convert all images to base64
358	        const images = clone.querySelectorAll('img');
359	        const originalImages = element.querySelectorAll('img');
360	
361	        // Create a map of src -> original img element for base64 conversion
362	        const srcToOriginal = new Map();
363	        originalImages.forEach(img => {
364	            const src = img.getAttribute('src');
365	            if (src && !srcToOriginal.has(src)) {
366	                srcToOriginal.set(src, img);
367	            }
368	        });
369	
370	        // Convert each image to base64
371	        for (const img of images) {
372	            const src = img.getAttribute('src') || '';
373	            // Skip small icons and UI images
374	            if (src.includes('favicon') || src.includes('avatar') ||
375	                (img.className && img.className.includes('icon'))) {
376	                continue;
377	            }
378	
379	            // Use original image element for conversion (it has the actual image data)
380	            const originalImg = srcToOriginal.get(src);
381	            if (originalImg) {
382	                const base64 = await imageToBase64(originalImg);
383	                if (base64) {
384	                    img.setAttribute('data-base64', base64);
385	                }
386	            }
387	        }
388	
389	        // Find the markdown content container if it exists
390	        const markdownContainer = clone.querySelector('.markdown, [class*="markdown"]');
391	        const contentElement = markdownContainer || clone;
392	
393	        // Convert to markdown
394	        let markdown = convertElementToMarkdown(contentElement);
395	
396	        // Clean up the result
397	        return cleanMarkdown(markdown);
398	    }
