491	    function identifySender(messageElement, index, allMessages) {
492	        // Method 1: Check for data attributes (most reliable)
493	        const authorRole = messageElement.getAttribute('data-message-author-role');
494	        if (authorRole) {
495	            return { sender: authorRole === 'user' ? 'You' : 'ChatGPT', reliable: true };
496	        }
497	
498	        // Method 2: Look for avatar images with better detection
499	        const avatars = messageElement.querySelectorAll('img');
500	        for (const avatar of avatars) {
501	            const alt = avatar.alt?.toLowerCase() || '';
502	            const src = avatar.src?.toLowerCase() || '';
503	            const classes = avatar.className?.toLowerCase() || '';
504	
505	            // User indicators
506	            if (alt.includes('user') || src.includes('user') || classes.includes('user')) {
507	                return { sender: 'You', reliable: false };
508	            }
509	
510	            // Assistant indicators
511	            if (alt.includes('chatgpt') || alt.includes('assistant') || alt.includes('gpt') ||
512	                src.includes('assistant') || src.includes('chatgpt') || classes.includes('assistant')) {
513	                return { sender: 'ChatGPT', reliable: false };
514	            }
515	        }
516	
517	        // Method 3: Content analysis with better patterns
518	        const text = messageElement.textContent.toLowerCase();
519	        const textStart = text.substring(0, 200); // Look at beginning of message
520	
521	        // Strong ChatGPT indicators
522	        if (textStart.match(/^(i understand|i can help|here's|i'll|let me|i'd be happy|certainly|of course)/)) {
523	            return { sender: 'ChatGPT', reliable: false };
524	        }
525	
526	        // Strong user indicators
527	        if (textStart.match(/^(can you|please help|how do i|i need|i want|help me|could you)/)) {
528	            return { sender: 'You', reliable: false };
529	        }
530	
531	        // Method 4: Structural analysis - look at DOM structure
532	        const hasCodeBlocks = messageElement.querySelectorAll('pre, code').length > 0;
533	        const hasLongText = messageElement.textContent.length > 200;
534	        const hasLists = messageElement.querySelectorAll('ul, ol, li').length > 0;
535	
536	        // ChatGPT messages tend to be longer and more structured
537	        if (hasCodeBlocks && hasLongText && hasLists) {
538	            return { sender: 'ChatGPT', reliable: false };
539	        }
540	
541	        // Method 5: Position-based fallback with better logic
542	        // Try to detect actual alternating pattern by looking at content characteristics
543	        if (index > 0 && allMessages[index - 1]) {
544	            const prevText = allMessages[index - 1].textContent;
545	            const currentText = messageElement.textContent;
546	
547	            // If previous was short and current is long, likely user -> assistant
548	            if (prevText.length < 100 && currentText.length > 300) {
549	                return { sender: 'ChatGPT', reliable: false };
550	            }
551	
552	            // If previous was long and current is short, likely assistant -> user
553	            if (prevText.length > 300 && currentText.length < 100) {
554	                return { sender: 'You', reliable: false };
555	            }
556	        }
557	
558	        // Final fallback
559	        return { sender: index % 2 === 0 ? 'You' : 'ChatGPT', reliable: false };
560	    }
