572	            const element = document.querySelector(selector);
573	            if (element && element.textContent.trim()) {
574	                const title = element.textContent.trim();
575	                // Avoid generic titles
576	                if (!['chatgpt', 'new chat', 'untitled', 'chat'].includes(title.toLowerCase())) {
577	                    return title;
