585	    // Main export logic
586	    const messages = findMessages();
587	    
588	    if (messages.length === 0) {
589	        alert('No messages found. The page structure may have changed.');
590	        return;
591	    }
592	
593	    console.log(`Processing ${messages.length} messages...`);
594	
595	    const lines = [];
596	    const title = extractConversationTitle();
597	    const date = formatDate();
598	    const url = window.location.href;
599	
600	    lines.push(`# ${title}\n`);
601	    lines.push(`**Date:** ${date}`);
602	    lines.push(`**Source:** [chat.openai.com](${url})\n`);
603	    lines.push(`---\n`);
